class Component extends DCLogic {
  rootRef = React.createRef();

  tree = [
    { id: 'db1', t: 'db', l: 'Primary' },
    { id: 'db2', t: 'db', l: 'Primarywer' },
    { id: 'db3', t: 'db', l: '4.5.4' },
    { id: 'db4', t: 'db', l: 'Primary2', k: [
      { id: 'nf1', t: 'feeder', l: 'New Feeder', c: '192' },
      { id: 'cen', t: 'folder', l: 'CEN_P_240484_03_Sec10_K…' },
      { id: 'sg', t: 'device', l: 'SG', c: '1' },
      { id: 'bktp', t: 'device', l: 'БКТПБ4', c: '30', k: [
        { id: 's1', t: 'section', l: 'Секция 1', c: '15' },
        { id: 's2', t: 'section', l: 'Секция 2', c: '15', k: [
          { id: 'ov', t: 'cell', l: 'ОВ', c: '5' },
          { id: 'rv', t: 'cell', l: 'РВ', c: '5' },
          { id: 't2', t: 'cell', l: 'Т2', c: '5' }
        ] }
      ] }
    ] },
    { id: 'rec', t: 'folder', l: 'Rec35-SIB-25-07-0002 АЧР', k: [
      { id: 'nfid', t: 'feeder', l: 'Новый фидер', c: '5', k: [
        { id: 'v35', t: 'cell', l: 'В-35 Отпайка №2', c: '5' }
      ] }
    ] },
    { id: 'krul', t: 'device', l: 'КРУ LOCAL', c: '27…', k: [
      { id: 's0', t: 'section', l: 'Секция 0', k: [
        { id: 'ov0', t: 'cell', l: 'ОВ' },
        { id: 'ol2', t: 'cell', l: 'ОЛ 2' },
        { id: 'ol4', t: 'cell', l: 'ОЛ 4' }
      ] },
      { id: 's3', t: 'section', l: 'Секция 3', c: '27…', k: [
        { id: 'ov3', t: 'cell', l: 'ОВ', c: '27…' },
        { id: 'ol23', t: 'cell', l: 'ОЛ 2' },
        { id: 'ol43', t: 'cell', l: 'ОЛ 4' }
      ] },
      { id: 's11', t: 'section', l: 'Секция 1' }
    ] },
    { id: 'osn', t: 'db', l: 'Основная', k: [
      { id: 'kru2', t: 'device', l: 'КРУ', k: [
        { id: 'sec4', t: 'section', l: 'Section 4', k: [
          { id: 'mi', t: 'cell', l: 'MI' },
          { id: 'of2', t: 'cell', l: 'OF 2' },
          { id: 'of4', t: 'cell', l: 'OF 4' }
        ] }
      ] }
    ] },
    { id: 'rem', t: 'feeder', l: 'Remote', c: '8', k: [
      { id: 'cm15r', t: 'device', l: 'CM15_4_Rad_IP93', c: '8' }
    ] },
    { id: 'raevo', t: 'db', l: 'Раево_2.1_ПО 78' },
    { id: 'db417', t: 'db', l: 'DB_417', k: [
      { id: 'nf2', t: 'feeder', l: 'New Feeder', c: '156', k: [
        { id: 'r1', t: 'device', l: 'R1', c: '156' },
        { id: 'cm15rre', t: 'device', l: 'CM15_4_RRE' },
        { id: 'cm17', t: 'device', l: 'CM17_0_RRE' }
      ] }
    ] }
  ];

  navTree = [
    { id: 'sys', l: 'Системные параметры', k: [
      { id: 'config', l: 'Конфигурация' },
      { id: 'exch', l: 'Межсекционный обмен' },
      { id: 'sect', l: 'Секция' },
      { id: 'rtc', l: 'Часы реального времени' }
    ] },
    { id: 'panel', l: 'Панель управления', k: [
      { id: 'common', l: 'Общие настройки' },
      { id: 'btns', l: 'Настройки кнопок' },
      { id: 'leds', l: 'Настройки светодиодов' }
    ] },
    { id: 'meas', l: 'Измерения' },
    { id: 'cnt', l: 'Счетчики и журналы', k: [
      { id: 'loadj', l: 'Журнал нагрузок' },
      { id: 'osc', l: 'Осциллограф' },
      { id: 'harm', l: 'Гармоники' },
      { id: 'fl', l: 'Определение места повреждения' }
    ] },
    { id: 'eth', l: 'Настройки Ethernet' },
    { id: 'line', l: 'Параметры линии' }
  ];

  tables = {
    config: [
      { id: 'si', g: 'Сис. инфо', rows: [
        { l: 'Прошивка v.', d: '76.02.3', f: '76.02.3' },
        { l: 'Функциональность', d: 'ФРВ', f: 'ФРВ' }
      ] },
      { id: 'cfg', g: 'Конфигурация', rows: [
        { l: 'Функциональность', d: 'ФРВ_I(3)', f: 'ФРВ_I(3)' },
        { l: 'Подфункциональность', d: 'Двунаправленный', f: 'Двунаправленный' },
        { l: 'Тип модуля управления', d: '15_3I', f: '15_3I' },
        { l: 'Тип коммутационного модуля', d: 'ISM15_Mono_1_S', f: 'ISM15_Mono_1_S', ch: 1 },
        { l: 'Номинальное напряжение', u: 'кВ', d: '10,50', f: '10,50' },
        { l: 'Номинальная частота', u: 'Гц', d: '50', f: '50' }
      ] }
    ],
    sect: [
      { id: 'sec', g: 'Секция', rows: [
        { l: '№ секции', d: '2', f: '2' },
        { l: '№ фидера', d: '1', f: '1' }
      ] }
    ],
    eth: [
      { id: 'eth', g: 'Настройки Ethernet', rows: [
        { l: 'IP-адрес', d: '192.168.102.13', f: '192.168.102.13' },
        { l: 'Маска подсети', d: '255.255.255.0', f: '255.255.255.0' },
        { l: 'Порт', d: '9001', f: '9001' }
      ] }
    ],
    rtc: [
      { id: 'rtc', g: 'Часы реального времени', rows: [
        { l: 'Дата', d: '01.07.2026', f: '17.02.2026', ch: 1 },
        { l: 'Время', d: '23:44:21', f: '10:12:05', ch: 1 }
      ] }
    ]
  };

  cellMap = {
    rv: { func: '(ФРВ) Фидер резервного ввода', feeder: '1', section: '2' },
    ov: { func: '(ФВ) Фидер ввода', feeder: '1', section: '2' },
    t2: { func: '(ФТ) Фидер трансформатора', sub: 'Однонаправленный', feeder: '2', section: '2' },
    v35: { series: 'Rec35', func: '(АЧР) Частотная разгрузка', volt: '35' }
  };

  state = {
    q: '', sel: 'rv',
    exp: { db4: true, bktp: true, s2: true, rec: true, nfid: true, krul: true, s0: true, s3: true, osn: true, kru2: true, sec4: true, rem: true, db417: true, nf2: true },
    tab: 'obj',
    pOpen: { info: true, misc: true, cp: true, ust: true, jrn: true, res: true, log: true },
    serial: '20000605', pw: '123456', pwVis: false, iface: 'Ethernet', ip: '192.168.102.13', port: 9001,
    readAll: false, sysUpd: true, interval: 3,
    connected: false, connecting: false, log: [],
    menu: null,
    win: { open: true, x: 640, y: 110, max: false },
    winTitle: '[Секция 2 → РВ] — Системные настройки',
    navSel: 'config', navExp: { sys: true, panel: true, cnt: true }, winQ: '',
    grpClosed: {}, diffOnly: false, archive: '17.02.2026 10:12',
    status: ''
  };

  constructor(props) {
    super(props);
    const vw = typeof window !== 'undefined' ? window.innerWidth : 1440;
    const vh = typeof window !== 'undefined' ? window.innerHeight : 900;
    this.state.win.x = Math.max(340, vw - 726);
    this.state.win.y = Math.max(52, Math.round(vh * 0.13));
    this._timers = [];
    this._drag = null;
  }

  componentDidMount() {
    this._doc = () => { if (this.state.menu !== null) this.setState({ menu: null }); };
    this._mv = (e) => {
      const d = this._drag;
      if (!d) return;
      if (d.t === 'win') {
        const nx = Math.min(Math.max(e.clientX - d.ox, -280), (typeof window !== 'undefined' ? window.innerWidth : 1400) - 90);
        const ny = Math.max(e.clientY - d.oy, 40);
        this.setState(s => ({ win: Object.assign({}, s.win, { x: nx, y: ny }) }));
      } else if (d.t === 'int') {
        const v = Math.max(1, Math.min(10, d.v + Math.round((e.clientX - d.x) / 16)));
        if (v !== this.state.interval) this.setState({ interval: v });
      }
    };
    this._up = () => { this._drag = null; };
    this._rs = () => this.forceUpdate();
    document.addEventListener('mousedown', this._doc);
    document.addEventListener('mousemove', this._mv);
    document.addEventListener('mouseup', this._up);
    window.addEventListener('resize', this._rs);
    this.applyTheme();
  }

  componentDidUpdate() { this.applyTheme(); }

  componentWillUnmount() {
    document.removeEventListener('mousedown', this._doc);
    document.removeEventListener('mousemove', this._mv);
    document.removeEventListener('mouseup', this._up);
    window.removeEventListener('resize', this._rs);
    this._timers.forEach(clearTimeout);
    clearTimeout(this._st);
  }

  applyTheme() {
    const r = this.rootRef.current;
    if (!r) return;
    const p = this.props;
    r.style.zoom = String(p.uiScale == null ? 1 : p.uiScale);
    r.style.setProperty('--tl-accent', p.accent || '#4772B3');
    const d = p.density || 'Стандартная';
    r.style.setProperty('--tl-row', d === 'Компактная' ? '17px' : d === 'Просторная' ? '24px' : '20px');
  }

  setStatus(t) {
    clearTimeout(this._st);
    this.setState({ status: t });
    this._st = setTimeout(() => this.setState({ status: '' }), 4200);
  }

  addLog(m) {
    const t = new Date().toLocaleTimeString('ru-RU', { hour12: false });
    this.setState(s => ({ log: s.log.concat([{ t: t, m: m }]) }));
  }

  later(ms, fn) { this._timers.push(setTimeout(fn, ms)); }

  togMenu(id, e) { e.stopPropagation(); this.setState(s => ({ menu: s.menu === id ? null : id })); }
  togExp(id) { this.setState(s => { const o = Object.assign({}, s.exp); o[id] = !o[id]; return { exp: o }; }); }
  togNav(id) { this.setState(s => { const o = Object.assign({}, s.navExp); o[id] = !o[id]; return { navExp: o }; }); }
  togPanel(k) { this.setState(s => { const o = Object.assign({}, s.pOpen); o[k] = !o[k]; return { pOpen: o }; }); }

  iconFor(t) {
    const m = {
      db: { bg: '#8f8f8f', bd: 'none', rad: '2px', tf: 'none' },
      folder: { bg: '#b28a52', bd: 'none', rad: '2px', tf: 'none' },
      feeder: { bg: 'transparent', bd: '1.5px solid #9a9a9a', rad: '50%', tf: 'none' },
      section: { bg: 'transparent', bd: '1.5px solid #8f8f8f', rad: '2px', tf: 'none' },
      cell: { bg: '#E87D0D', bd: 'none', rad: '1.5px', tf: 'rotate(45deg) scale(0.85)' },
      device: { bg: '#7aa2d8', bd: 'none', rad: '50%', tf: 'none' }
    };
    return m[t] || m.cell;
  }

  findNode(id) {
    let f = null;
    const w = (l) => { l.forEach(n => { if (n.id === id) f = n; if (n.k) w(n.k); }); };
    w(this.tree);
    return f;
  }

  pathTo(id) {
    const res = [];
    const walk = (list, acc) => {
      for (let i = 0; i < list.length; i++) {
        const n = list[i];
        const a = acc.concat([n.l]);
        if (n.id === id) { res.push.apply(res, a); return true; }
        if (n.k && walk(n.k, a)) return true;
      }
      return false;
    };
    walk(this.tree, []);
    return res;
  }

  cellInfo() {
    const node = this.findNode(this.state.sel);
    const t = node ? node.t : 'cell';
    const kinds = { db: 'База данных', folder: 'Папка проекта', feeder: 'Фидер', section: 'Секция КРУ', device: 'Устройство', cell: 'Ячейка секции КРУ' };
    const base = { name: node ? node.l : 'РВ', kind: kinds[t] || 'Элемент', series: '—', func: '—', module: '—', sub: '—', feeder: '—', section: '—', volt: '—', freq: '—' };
    if (t === 'cell') Object.assign(base, { series: 'СМ15', func: '(ФОЛ) Фидер отходящей линии', module: '15_3I', sub: 'Двунаправленный', volt: '10,5', freq: '50' });
    if (t === 'device') Object.assign(base, { series: 'СМ15', module: '15_3I', volt: '10,5', freq: '50' });
    return Object.assign(base, this.cellMap[this.state.sel] || {});
  }

  getGroups() {
    const defs = this.tables[this.state.navSel] || [];
    const out = [];
    defs.forEach(grp => {
      let rows = grp.rows;
      if (this.state.diffOnly) rows = rows.filter(r => r.ch);
      if (!rows.length) return;
      const closed = !!this.state.grpClosed[grp.id];
      out.push({
        title: grp.g,
        arrow: closed ? '▸' : '▾',
        open: !closed,
        onTog: () => this.setState(s => { const o = Object.assign({}, s.grpClosed); o[grp.id] = !o[grp.id]; return { grpClosed: o }; }),
        rows: rows.map(r => ({
          label: r.l, unit: r.u || '', dev: r.d, file: r.f,
          fg: r.ch ? '#E9A15C' : '#d6d6d6', fw: r.ch ? 600 : 400,
          bg: r.ch ? 'rgba(232,125,13,.08)' : 'transparent'
        }))
      });
    });
    return out;
  }

  openWin() {
    const p = this.pathTo(this.state.sel);
    let t = 'Системные настройки';
    if (p.length >= 2) t = '[' + p[p.length - 2] + ' → ' + p[p.length - 1] + '] — Системные настройки';
    else if (p.length === 1) t = '[' + p[0] + '] — Системные настройки';
    this.setState(s => ({ win: Object.assign({}, s.win, { open: true }), winTitle: t }));
  }

  connect() {
    const s = this.state;
    if (s.connecting) return;
    if (s.connected) {
      this.addLog('Соединение закрыто пользователем');
      this.setState({ connected: false });
      this.setStatus('Устройство отключено');
      return;
    }
    this.setState({ connecting: true });
    this.addLog('Подключение к ' + s.ip + ':' + s.port + ' (' + s.iface + ')…');
    this.later(700, () => { this.addLog('Соединение установлено'); this.addLog('Серийный номер подтверждён: ' + this.state.serial); });
    this.later(1400, () => {
      this.addLog('Чтение системного статуса… ОК');
      this.setState({ connected: true, connecting: false });
      this.setStatus('Устройство подключено: СМ15 №' + this.state.serial);
    });
  }

  ping() {
    this.addLog('PING ' + this.state.ip + ' — ответ 2 мс');
    this.setStatus('Ping ' + this.state.ip + ': ответ 2 мс');
  }

  renderVals() {
    const s = this.state;
    const acc = 'var(--tl-accent,#4772B3)';

    const q = s.q.trim().toLowerCase();
    const vis = (n) => { if (!q) return true; if (n.l.toLowerCase().indexOf(q) >= 0) return true; return (n.k || []).some(vis); };
    const rows = [];
    let zi = 0;
    const emit = (list, depth) => {
      list.forEach(n => {
        if (!vis(n)) return;
        const has = !!(n.k && n.k.length);
        const open = q ? true : !!s.exp[n.id];
        const seld = s.sel === n.id;
        const ic = this.iconFor(n.t);
        const i = zi++;
        rows.push({
          pad: 4 + depth * 13,
          arrow: has ? (open ? '▾' : '▸') : '',
          ibg: ic.bg, ibd: ic.bd, irad: ic.rad, itf: ic.tf,
          label: n.l, count: n.c || '',
          bg: seld ? acc : (i % 2 ? 'rgba(255,255,255,.02)' : 'transparent'),
          fg: seld ? '#ffffff' : (n.t === 'cell' || n.t === 'device' ? '#d8d8d8' : '#c4c4c4'),
          cfg: seld ? '#ffe1c4' : '#c2854d',
          onSel: () => this.setState({ sel: n.id }),
          onDbl: () => { if (has) this.togExp(n.id); },
          onTog: (e) => { e.stopPropagation(); if (has) this.togExp(n.id); }
        });
        if (has && open) emit(n.k, depth + 1);
      });
    };
    emit(this.tree, 0);

    const cell = this.cellInfo();
    const crumb = this.pathTo(s.sel).join('  ▸  ') || '—';

    const mk = (label, hint) => ({
      label: label, hint: hint || '',
      onPick: (e) => { e.stopPropagation(); this.setState({ menu: null }); this.setStatus('Демо: «' + label + '»'); }
    });
    const addItems = [mk('База данных', 'Ctrl N'), mk('Фидер', ''), mk('Ячейка КРУ', ''), mk('Импорт из файла…', 'Ctrl I')];
    const utilsItems = [mk('Сравнение конфигураций…', ''), mk('Обновление прошивки…', ''), mk('Экспорт журналов…', ''), mk('Настройки приложения…', 'Ctrl ,')];
    const helpItems = [mk('Руководство пользователя', 'F1'), mk('Горячие клавиши', ''), mk('О программе TELARM Lite', '')];

    const ifaceItems = ['Ethernet', 'RS-485', 'USB'].map(o => ({
      label: o, mark: s.iface === o ? '•' : '',
      onPick: (e) => { e.stopPropagation(); this.setState({ iface: o, menu: null }); }
    }));

    const histItems = ['17.02.2026 10:12', '14.10.2025 13:25'].map(d => ({
      label: 'Архив от ' + d, mark: s.archive === d ? '•' : '',
      onPick: (e) => { e.stopPropagation(); this.setState({ archive: d, menu: null }); this.setStatus('Загружен архив от ' + d); }
    }));

    const exportItems = [
      { label: 'Экспорт «Системные настройки»', onPick: (e) => { e.stopPropagation(); this.setState({ menu: null }); this.setStatus('Экспортировано: «Системные настройки» (демо)'); } },
      { label: 'Экспорт всех разделов…', onPick: (e) => { e.stopPropagation(); this.setState({ menu: null }); this.setStatus('Экспортированы все разделы (демо)'); } }
    ];

    const ustDefs = [
      ['Системные', '1', '#9a9a9a', true],
      ['Защита (РЗА)', '192', '#cf6b4d', false],
      ['Коммуникационные', '', '#7aa2d8', false],
      ['Пользовательские сигналы', '5', '#5fae8f', false],
      ['Коммерческий учёт', '', '#c9a44a', false]
    ];
    const ustRows = ustDefs.map(d => ({
      label: d[0], count: d[1], icon: d[2],
      onPick: () => {
        if (d[3]) { this.openWin(); this.setStatus('Открыто окно «Системные настройки»'); }
        else this.setStatus('Раздел «' + d[0] + '» — в этом прототипе не реализован');
      }
    }));

    const jrnRows = ['Состояние системы', 'События', 'Аварии', 'Журнал нагрузок', 'Неисправности', 'Изменения', 'Журнал связи', 'Осциллограммы', 'Профиль учёта энергии', 'События комм. учёта', 'Изменения комм. учёта', 'Журнал учёта энергии'].map(nm => ({
      label: nm,
      onPick: () => {
        if (this.state.connected) { this.addLog('Чтение журнала «' + nm + '»… ОК'); this.setStatus('Журнал «' + nm + '» прочитан'); }
        else this.setStatus('Журнал «' + nm + '»: устройство не подключено');
      }
    }));

    const resRows = ['Циклы ВО', 'Износ контактов'].map(nm => ({
      label: nm,
      onPick: () => this.setStatus(this.state.connected ? 'Счётчик «' + nm + '» прочитан' : 'Счётчики доступны после подключения')
    }));

    const wq = s.winQ.trim().toLowerCase();
    const nvis = (n) => { if (!wq) return true; if (n.l.toLowerCase().indexOf(wq) >= 0) return true; return (n.k || []).some(nvis); };
    const navRows = [];
    const emitN = (list, depth) => {
      list.forEach(n => {
        if (!nvis(n)) return;
        const has = !!(n.k && n.k.length);
        const open = wq ? true : !!s.navExp[n.id];
        const seld = s.navSel === n.id;
        navRows.push({
          pad: 4 + depth * 12,
          arrow: has ? (open ? '▾' : '▸') : '',
          label: n.l,
          bg: seld ? acc : 'transparent',
          fg: seld ? '#ffffff' : '#c9c9c9',
          onPick: () => { if (has) this.togNav(n.id); else this.setState({ navSel: n.id }); },
          onTog: (e) => { e.stopPropagation(); if (has) this.togNav(n.id); }
        });
        if (has && open) emitN(n.k, depth + 1);
      });
    };
    emitN(this.navTree, 0);

    const groups = this.getGroups();
    const winEmpty = groups.length === 0;
    const winEmptyText = s.diffOnly ? 'Различий не найдено' : 'Нет параметров для отображения — раздел пуст';

    const vw = typeof window !== 'undefined' ? window.innerWidth : 1440;
    const vh = typeof window !== 'undefined' ? window.innerHeight : 900;
    const winL = s.win.max ? 14 : s.win.x;
    const winT = s.win.max ? 46 : s.win.y;
    const winW = s.win.max ? Math.max(680, vw - 28) : 700;
    const winH = s.win.max ? Math.max(440, vh - 78) : 540;

    return {
      rootRef: this.rootRef,
      onAddBtn: (e) => this.togMenu('add', e), showAdd: s.menu === 'add', addItems: addItems,
