    return {
      isBool: isBool, isText: !isBool,
      text: isBool ? '' : String(v),
      mark: isBool && v ? '✓' : '',
      boxBg: isBool ? (v ? acc : '#3a3a3a') : '#3a3a3a',
      fg: diff ? '#E9A15C' : (row.nd ? '#ececec' : '#d6d6d6'),
      fw: (diff || row.nd) ? 600 : 400,
      bg: diff ? '#3a2a16' : '#1f1f1f',
      diff: diff
    };
  }

  diffCountFor(nodeId, cols) {
    const def = this.tables[nodeId];
    if (!def) return 0;
    let n = 0;
    def.rows.forEach(r => { if (cols.some(c => this.valueFor(r, c) !== r.db)) n++; });
    return n;
  }

  mkGroup(id, title, rowsDef, cols, acc) {
    let rs = rowsDef.map(r => {
      const cells = cols.map(c => this.cellFor(r, c, acc));
      return { label: r.l, unit: r.u || '', cells: cells, any: cells.some(x => x.diff) };
    });
    if (this.state.diffOnly) rs = rs.filter(r => r.any);
    if (!rs.length) return null;
    const closed = !!this.state.grpClosed[id];
    return {
      title: title,
      arrow: closed ? '▸' : '▾',
      open: !closed,
      onTog: () => this.setState(s => { const o = Object.assign({}, s.grpClosed); o[id] = !o[id]; return { grpClosed: o }; }),
      rows: rs
    };
  }

  openWin() {
    const p = this.pathTo(this.state.sel);
    let t = 'Системные настройки';
    if (p.length >= 2) t = '[' + p[p.length - 2] + ' → ' + p[p.length - 1] + '] — Системные настройки';
    else if (p.length === 1) t = '[' + p[0] + '] — Системные настройки';
    this.setState(s => ({ win: Object.assign({}, s.win, { open: true }), winTitle: t }));
  }

  openHist() {
    const sel = {};
    this.state.archCols.forEach(id => { sel[id] = true; });
    this.setState({ histOpen: true, histSel: sel });
  }

  connect() {
    const s = this.state;
    if (s.connecting) return;
    if (s.connected) {
      this.addLog('Соединение закрыто пользователем');
      this.setState({ connected: false });
      this.setStatus('Устройство отключено');
      return;
    }
    this.setState({ connecting: true });
    this.addLog('Подключение к ' + s.ip + ':' + s.port + ' (' + s.iface + ')…');
    this.later(700, () => { this.addLog('Соединение установлено'); this.addLog('Серийный номер подтверждён: ' + this.state.serial); });
    this.later(1400, () => {
      this.addLog('Чтение системного статуса… ОК');
      this.setState({ connected: true, connecting: false });
      this.setStatus('Устройство подключено: СМ15 №' + this.state.serial);
    });
  }

  ping() {
    this.addLog('PING ' + this.state.ip + ' — ответ 2 мс');
