parseDt(str) {
  const m = str.split(' ');
  const d = m[0].split('.');
  const t = (m[1] || '0:0:0.0').split(':');
  const sec = (t[2] || '0.0').split('.');
  return new Date(+d[2], +d[1] - 1, +d[0], +t[0], +t[1], +sec[0], +(sec[1] || 0)).getTime();
}

wave(id, t) {
  const S = Math.sin;
  if (id === 'ub') return (t >= 556 && t <= 574) ? 0.9 : 0;
  if (id === 'ua' || id === 'uc') return 0;
  if (id === 'ia') return t < 560 ? S(t / 1000 * 2 * Math.PI * 50) * 0.8 : 0;
  if (id === 'ib') return t < 560 ? S(t / 1000 * 2 * Math.PI * 50 - 2.09) * 0.8 : 0;
  if (id === 'ic') return t < 560 ? S(t / 1000 * 2 * Math.PI * 50 + 2.09) * 0.8 : 0;
  if (id === 'in') return t < 560 ? S(t / 1000 * 2 * Math.PI * 50) * 0.06 : 0;
  if (id === 'pv') return t < 560 ? 0.8 : 0;
  if (id === 'gt') return 0.8;
  if (id === 'zmn') return (t >= 540 && t <= 640) ? 0.8 : 0;
  if (id === 'apv') return (t >= 560 && t <= 720) ? 0.8 : 0;
  if (id === 'zmn2') return (t >= 545 && t <= 660) ? 0.8 : 0;
  return 0;
}

buildPts(id, w, h, dur, bip) {
  const pts = [];
  const step = Math.max(2, Math.floor(w / 420));
  for (let x = 0; x <= w; x += step) {
    const t = x / w * dur;
    const v = this.wave(id, t);
    const y = bip ? (h / 2 - v * (h / 2 - 10)) : (h - 12 - v * (h - 24));
    pts.push(x.toFixed(1) + ',' + y.toFixed(1));
  }
  return pts.join(' ');
}

valAt(ch, t) {
  const v = this.wave(ch.id, t);
  if (ch.dig) return v > 0.4 ? '1' : '0';
  if (ch.unit === 'В') {
    const kv = Math.abs(v) * 5.8;
    return kv < 0.005 ? '0 В' : (kv.toFixed(2).replace('.', ',') + ' кВ');
  }
  const a = Math.abs(v) * 400;
  return a < 0.5 ? '0 А' : (Math.round(a) + ' А');
}

