readJournal(nm) {
  if (!this.state.connected) { this.setStatus('Устройство не подключено'); return; }
  if (this.state.jrnProg[nm] != null) return;
  const isOsc = nm === 'Осциллограммы';
  this._jrnTimers = this._jrnTimers || {};
  this.addLog('Чтение журнала «' + nm + '»…');
  this.setState(s => { const o = Object.assign({}, s.jrnProg); o[nm] = 0; return { jrnProg: o }; });
  this._jrnTimers[nm] = setInterval(() => {
    const cur = this.state.jrnProg[nm];
    if (cur == null) { clearInterval(this._jrnTimers[nm]); delete this._jrnTimers[nm]; return; }
    const step = isOsc ? (2 + Math.random() * 4) : (8 + Math.random() * 12);
    const next = cur + step;
    if (next >= 100) {
      clearInterval(this._jrnTimers[nm]); delete this._jrnTimers[nm];
      const src = this.journals[nm];
      const n = src ? src.rows.length : 0;
      this.setState(s => {
        const o = Object.assign({}, s.jrnProg); delete o[nm];
        const jr = Object.assign({}, s.jrnRead); jr[nm] = true;
        return { jrnProg: o, jrnRead: jr };
      });
      this.addLog('Журнал «' + nm + '» вычитан (' + n + ' зап.)');
      this.setStatus('Журнал «' + nm + '» вычитан');
    } else {
      this.setState(s => { const o = Object.assign({}, s.jrnProg); o[nm] = next; return { jrnProg: o }; });
    }
  }, isOsc ? 240 : 190);
}

